{
  "name": "opencode-step-pause",
  "version": "0.1.0",
  "description": "OpenCode V2 plugin: periodic in-chat progress checkpoints every N steps, without extra turns or waiting for the user.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "tsx --test test/*.test.ts",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "progress",
    "progress-report",
    "checkpoint",
    "step",
    "long-running-tasks",
    "llm"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tkhs101/opencode-step-pause.git"
  },
  "homepage": "https://github.com/tkhs101/opencode-step-pause#readme",
  "bugs": {
    "url": "https://github.com/tkhs101/opencode-step-pause/issues"
  },
  "dependencies": {
    "@opencode/ai": "2.2.1",
    "@opencode/plugin": "2.2.1"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "tsx": "^4.20.0",
    "typescript": "^5.9.0"
  }
}
